<?php declare(strict_types=1); namespace App\Http\Controllers\Public; use App\Http\Controllers\Controller; use App\Http\Requests\Pmbm\StoreApplicantRequest; use App\Models\AcademicYear; use App\Models\Pmbm\{PmbmApplicant,PmbmSetting,PmbmDocumentRequirement}; use App\Services\Pmbm\PmbmRegistrationService; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\View\View;
class PmbmRegistrationController extends Controller { public function index():View{$settings=PmbmSetting::with('academicYear')->where('enabled',true)->latest()->first();return view('pmbm.public.index',compact('settings'));} public function create():View{return view('pmbm.public.form',['years'=>AcademicYear::orderByDesc('starts_at')->get(),'requirements'=>PmbmDocumentRequirement::where('is_active',true)->orderBy('sort_order')->get()]);} public function store(StoreApplicantRequest $request,PmbmRegistrationService $service):RedirectResponse{$a=$service->submit($request->validated(),'online');return redirect()->route('pmbm.status.show',['number'=>$a->registration_number,'token'=>$a->public_token])->with('status','Pendaftaran berhasil dikirim.');} public function statusForm():View{return view('pmbm.public.status');} public function status(Request $request):View{$data=$request->validate(['number'=>'required|string','token'=>'required|string|size:64']);$applicant=PmbmApplicant::where('registration_number',$data['number'])->where('public_token',$data['token'])->firstOrFail();return view('pmbm.public.status',compact('applicant'));} }
